).CALCULATE(
    supplier_id=supplier_id,
    avg_amount_purchased=AVG(product_supplier.total_amount_purchased)
).WHERE(
    (avg_amount_purchased > 50000) | (avg_amount_purchased < 30000)
).CALCULATE(
    supplier_id=supplier_id
)

# Find customers who made orders after the earliest cancelled order date
customers_after_cancelled = customer_order.WHERE(
    order_date > customer_order.WHERE(order_status_code == "Cancelled").CALCULATE(
        min_cancelled_date = MIN(order_date)
    ).min_cancelled_date.SINGULAR()
).PARTITION(name="customers", by=customer_id).CALCULATE(
    customer_id = customer_id
)

# Find staff whose assignment date is earlier than any clerical staff
result = department_store.CALCULATE(
    latest_clerical_date = MAX(staff_department_assignment.WHERE(
        job_title_code == "Clerical Staff"
    ).date_assigned_to)
).staff_department_assignment.WHERE(
    date_assigned_to < latest_clerical_date
).CALCULATE(
    staff_id = staff_id
)

customers_with_tn_address = customer.WHERE(
