)

# Filter airports in London and sum their domestic passengers
london_domestic_total = airports.WHERE(
    CONTAINS(airport_name, "London")
).CALCULATE(
    total_domestic_passengers=SUM(domestic_passengers)
)

# Filter airports containing "London" in their name and sum domestic passengers
london_airports_domestic_total = airports.WHERE(
    LIKE(airport_name, "%London%")
).CALCULATE(
    total_domestic_passengers=SUM(domestic_passengers)
)

# Find airports visited by Robinson R-22 and calculate average passengers
robinson_airports_avg = Aircraft.WHERE(
    Aircraft == "Robinson R-22"
).airport_aircraft.airport.CALCULATE(
    avg_passengers = AVG(Total_Passengers)
)

# Find aircraft associated with both London Heathrow and Gatwick airports
aircraft_at_both_airports = airport_aircraft.WHERE(
    (airport.airport_name == "London Heathrow") |
    (airport.airport_name == "Gatwick")
).CALCULATE(
    aircraft_name=aircraft.aircraft,
    airport_name=airport.airport_name
).PARTITION(name="aircraft_groups", by=aircraft_name).WHERE(
    COUNT(airport_aircraft) == 2
).CALCULATE(
    aircraft_name=aircraft_name
)

# Count distinct locations where things with 'Unsatisfied' service details have been located
distinct_locations_count = local_govt_and_lot.CALCULATE(
    distinct_location_count = NDISTINCT(thing.WHERE(
        service_details == 'Unsatisfied'
    ).timed_locations_of_thing.location_code)
)

# Find aircraft that have won matches at least twice
aircraft_with_multiple_wins = matches.PARTITION(
    name="aircraft_groups", 
    by=winning_aircraft
).WHERE(
    COUNT(matches) >= 2
).CALCULATE(
    aircraft_name=matches.aircraft.aircraft
)

